import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Sistem Peradilan dan Mekanisme Putusan","description":"","frontmatter":{},"headers":[],"relativePath":"id/48-司法体系与裁决机制.md","filePath":"id/48-司法体系与裁决机制.md"}'),s={name:"id/48-司法体系与裁决机制.md"};function r(d,a,k,l,u,m){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="sistem-peradilan-dan-mekanisme-putusan" tabindex="-1">Sistem Peradilan dan Mekanisme Putusan <a class="header-anchor" href="#sistem-peradilan-dan-mekanisme-putusan" aria-label="Permalink to &quot;Sistem Peradilan dan Mekanisme Putusan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>48</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Pengadilan Simbiosis, Independensi Peradilan, Mekanisme Putusan, Peradilan Antar-Ras, Tinjauan Inkonstitusional</td></tr></tbody></table><h2 id="i-posisi-dan-prinsip-sistem-peradilan" tabindex="-1">I. Posisi dan Prinsip Sistem Peradilan <a class="header-anchor" href="#i-posisi-dan-prinsip-sistem-peradilan" aria-label="Permalink to &quot;I. Posisi dan Prinsip Sistem Peradilan&quot;">​</a></h2><p>Sistem peradilan adalah pilar penting dari kerangka tata kelola peradaban simbiosis jangkar, sejajar dengan kekuatan legislatif (Dewan Jangkar) dan kekuatan eksekutif (Komite Eksekutif Simbiosis), dan menjalankan kekuasaan kehakiman secara independen. 《Konstitusi Simbiosis》 menetapkan struktur tata kelola &quot;pemisahan dan keseimbangan tiga kekuatan&quot;, dan sistem peradilan adalah garis pertahanan akhir untuk menjaga martabat konstitusi, melindungi hak semua makhluk, dan menyelesaikan sengketa sosial.</p><p>Sistem peradilan Hengyuanzhou menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Independensi Peradilan</td><td>Pengadilan menjalankan kekuasaan kehakiman secara independen sesuai hukum, tanpa campur tangan lembaga administratif, organisasi sosial, dan individu</td></tr><tr><td>Prinsip Keadilan Peradilan</td><td>Kegiatan peradilan didasarkan pada fakta dan menggunakan hukum sebagai tolok ukur, memastikan keadilan prosedural dan keadilan substantif</td></tr><tr><td>Prinsip Keterbukaan Peradilan</td><td>Kegiatan peradilan dilakukan secara terbuka sesuai hukum, dokumen pengadilan dipublikasikan, dan menerima pengawasan sosial</td></tr><tr><td>Prinsip Kesetaraan Semua Ras</td><td>Semua makhluk setara di hadapan peradilan, dan penerapan hukum tidak membedakan ras, tingkat kultivasi, atau asal-usul</td></tr><tr><td>Prinsip Kemudahan Peradilan</td><td>Layanan peradilan harus memudahkan semua makhluk, mengurangi biaya litigasi, dan menyediakan berbagai jalur penyelesaian sengketa</td></tr><tr><td>Prinsip Putusan Akhir</td><td>Menerapkan sistem dua tingkat sebagai tingkat akhir, dan putusan akhir memiliki efek final, menjaga otoritas peradilan</td></tr></tbody></table><h2 id="ii-sistem-organisasi-pengadilan" tabindex="-1">II. Sistem Organisasi Pengadilan <a class="header-anchor" href="#ii-sistem-organisasi-pengadilan" aria-label="Permalink to &quot;II. Sistem Organisasi Pengadilan&quot;">​</a></h2><p>Sistem organisasi pengadilan peradaban simbiosis jangkar dibagi menjadi empat tingkat, dan menerapkan sistem dua tingkat sebagai tingkat akhir:</p><table tabindex="0"><thead><tr><th>Tingkat</th><th>Nama Pengadilan</th><th>Wilayah Kewenangan</th><th>Fungsi Utama</th></tr></thead><tbody><tr><td>Tingkat Pertama</td><td>Pengadilan Simbiosis Dasar</td><td>Kabupaten/Plano Kecil</td><td>Mengadili perkara perdata, pidana, administratif tingkat pertama, dan menyelesaikan sengketa sederhana</td></tr><tr><td>Tingkat Kedua</td><td>Pengadilan Simbiosis Regional</td><td>Kota/Wilayah/Plano Menengah</td><td>Mengadili perkara besar tingkat pertama dan perkara banding terhadap putusan pengadilan dasar</td></tr><tr><td>Tingkat Ketiga</td><td>Pengadilan Simbiosis Plano</td><td>Plano Besar/Grup Plano</td><td>Mengadili perkara sangat besar tingkat pertama dan perkara banding terhadap putusan pengadilan regional</td></tr><tr><td>Tingkat Keempat</td><td>Mahkamah Agung Simbiosis</td><td>Seluruh Alam Semesta</td><td>Mengadili perkara konstitusional tingkat pertama, perkara banding terhadap putusan pengadilan plano, dan tinjauan inkonstitusional</td></tr></tbody></table><p>Selain itu, pengadilan khusus didirikan sesuai kebutuhan:</p><ul><li><strong>Pengadilan Sengketa Kultivasi</strong>: Khusus mengadili sengketa sumber daya kultivasi, ganti rugi kerusakan kultivasi, sengketa etika kultivasi, dll.</li><li><strong>Pengadilan Antar-Ras</strong>: Khusus mengadili sengketa yang melibatkan ras yang berbeda, dilengkapi hakim dari setiap ras.</li><li><strong>Pengadilan Komersial Plano</strong>: Khusus mengadili sengketa komersial antar-plano dan perkara anti-monopoli.</li><li><strong>Pengadilan Makhluk Aneh</strong>: Khusus mengadili perkara khusus yang melibatkan makhluk aneh, energi aneh, dan tubuh pengganti gelap.</li></ul><h2 id="iii-sistem-hakim" tabindex="-1">III. Sistem Hakim <a class="header-anchor" href="#iii-sistem-hakim" aria-label="Permalink to &quot;III. Sistem Hakim&quot;">​</a></h2><p>Hakim adalah pelaksana kekuasaan kehakiman, dan kualitas serta independensinya secara langsung berkaitan dengan keadilan peradilan:</p><ol><li><strong>Syarat Pengangkatan Hakim</strong>: Hakim harus memiliki perilaku yang baik, pengetahuan hukum yang solid, dan pengalaman praktis yang kaya, dan hakim ras asing juga harus akrab dengan budaya dan karakteristik fisiologis rasnya sendiri.</li><li><strong>Proses Seleksi Hakim</strong>: Hakim dinominasikan oleh komite seleksi hakim independen dan diangkat oleh Dewan Jangkar, memastikan keadilan dan profesionalisme proses seleksi.</li><li><strong>Jaminan Identitas Hakim</strong>: Hakim tidak dapat diberhentikan, diturunkan jabatan, dipecat, atau dihukum tanpa alasan hukum dan tanpa proses hukum, memastikan hakim dapat mengadili secara independen.</li><li><strong>Sistem Penghindaran Hakim</strong>: Hakim yang memiliki kepentingan dengan pihak perkara atau hasil perkara harus menghindar dan tidak dapat berpartisipasi dalam pemeriksaan perkara.</li><li><strong>Sistem Hukuman Hakim</strong>: Hakim yang melakukan korupsi, suap, kecurangan, putusan sewenang-wenang, dll., akan dihukum sesuai hukum, dan yang构成 kejahatan akan dituntut tanggung jawab pidana.</li><li><strong>Kuota Hakim Ras Asing</strong>: Pengadilan di semua tingkat harus melengkapi proporsi tertentu hakim ras asing, memastikan pemeriksaan dapat mempertimbangkan budaya dan pengetahuan hukum setiap ras.</li></ol><h2 id="iv-proses-litigasi" tabindex="-1">IV. Proses Litigasi <a class="header-anchor" href="#iv-proses-litigasi" aria-label="Permalink to &quot;IV. Proses Litigasi&quot;">​</a></h2><h3 id="_1-proses-perdata" tabindex="-1">(1) Proses Perdata <a class="header-anchor" href="#_1-proses-perdata" aria-label="Permalink to &quot;(1) Proses Perdata&quot;">​</a></h3><p>Proses perdata menerapkan prinsip &quot;tidak ada gugatan tidak ada hakim&quot;, dan prosesnya meliputi:</p><ol><li><strong>Gugatan dan Penerimaan</strong>: Penggugat mengajukan gugatan kepada pengadilan yang berwenang, dan pengadilan memutuskan setelah peninjauan apakah menerima atau tidak.</li><li><strong>Persiapan Sebelum Pemeriksaan</strong>: Pengadilan mengirimkan salinan gugatan kepada tergugat, mengorganisir pertukaran bukti, dan menentukan titik sengketa.</li><li><strong>Pemeriksaan di Sidang</strong>: Penyelidikan pengadilan, perdebatan pengadilan, pernyataan terakhir pihak, dengan mediasi diprioritaskan.</li><li><strong>Putusan dan Eksekusi</strong>: Pengadilan mengeluarkan putusan sesuai hukum, dan pihak yang tidak puas dapat mengajukan banding dalam batas waktu hukum. Putusan yang efektif dieksekusi secara paksa oleh lembaga eksekusi.</li></ol><h3 id="_2-proses-pidana" tabindex="-1">(2) Proses Pidana <a class="header-anchor" href="#_2-proses-pidana" aria-label="Permalink to &quot;(2) Proses Pidana&quot;">​</a></h3><p>Proses pidana menerapkan prinsip &quot;praduga tidak bersalah&quot;, dan prosesnya meliputi:</p><ol><li><strong>Pendaftaran dan Penyelidikan</strong>: Lembaga penyelidik mendaftarkan dan menyelidiki tindak pidana, mengumpulkan bukti, dan mengambil tindakan paksa.</li><li><strong>Peninjauan dan Penuntutan</strong>: Lembaga penuntut meninjau hasil penyelidikan dan memutuskan apakah mengajukan penuntutan umum.</li><li><strong>Pemeriksaan</strong>: Pengadilan mengadakan sidang, pihak penuntut dan pembela mengajukan dan menguji bukti, dan pengadilan mengeluarkan putusan sesuai hukum.</li><li><strong>Eksekusi</strong>: Putusan yang efektif dieksekusi oleh lembaga eksekusi, termasuk eksekusi hukuman dan eksekusi ganti rugi perdata tambahan.</li></ol><h3 id="_3-proses-administratif" tabindex="-1">(3) Proses Administratif <a class="header-anchor" href="#_3-proses-administratif" aria-label="Permalink to &quot;(3) Proses Administratif&quot;">​</a></h3><p>Warga negara, badan hukum, atau organisasi lain yang menganggap tindakan administratif lembaga administratif melanggar hak sah mereka memiliki hak untuk mengajukan proses administratif kepada pengadilan. Proses administratif menerapkan &quot;pembalikan beban pembuktian&quot;, dan lembaga administratif tergugat harus memikul beban pembuktian atas legalitas tindakan administratifnya.</p><h3 id="_4-proses-konstitusional" tabindex="-1">(4) Proses Konstitusional <a class="header-anchor" href="#_4-proses-konstitusional" aria-label="Permalink to &quot;(4) Proses Konstitusional&quot;">​</a></h3><p>Semua makhluk yang menganggap hak dasar konstitusionalnya dilanggar dan telah menggunakan semua jalur perbaikan lainnya dapat langsung mengajukan proses konstitusional kepada Mahkamah Agung Simbiosis berdasarkan Konstitusi. Proses konstitusional adalah jalur perbaikan akhir untuk melindungi hak konstitusional.</p><h2 id="v-mekanisme-penyelesaian-sengketa-ganda" tabindex="-1">V. Mekanisme Penyelesaian Sengketa Ganda <a class="header-anchor" href="#v-mekanisme-penyelesaian-sengketa-ganda" aria-label="Permalink to &quot;V. Mekanisme Penyelesaian Sengketa Ganda&quot;">​</a></h2><p>Untuk mengurangi beban peradilan dan meningkatkan efisiensi penyelesaian sengketa, Negara mendirikan mekanisme penyelesaian sengketa ganda:</p><table tabindex="0"><thead><tr><th>Mekanisme</th><th>Wilayah Penerapan</th><th>Efek</th></tr></thead><tbody><tr><td>Negosiasi dan Kesepakatan</td><td>Semua sengketa perdata</td><td>Pihak memenuhi secara sukarela, tidak memiliki kekuatan eksekusi paksa</td></tr><tr><td>Mediasi Rakyat</td><td>Sengketa rakyat, sengketa tetangga</td><td>Kesepakatan mediasi memiliki kekuatan eksekusi paksa setelah konfirmasi yudisial oleh pengadilan</td></tr><tr><td>Mediasi Administratif</td><td>Sengketa administratif, sengketa ganti rugi perdata</td><td>Kesepakatan mediasi memiliki efek kontrak</td></tr><tr><td>Arbitase</td><td>Sengketa komersial, sengketa tenaga kerja</td><td>Putusan arbitase memiliki kekuatan eksekusi paksa, dengan arbitase tunggal dan final</td></tr><tr><td>Putusan Yudisial</td><td>Semua sengketa</td><td>Putusan akhir memiliki kekuatan eksekusi paksa final</td></tr></tbody></table><p>Negara mendorong pihak untuk memprioritaskan penyelesaian sengketa melalui cara non-litigasi, dan pengadilan juga harus melakukan mediasi selama proses litigasi.</p><h2 id="vi-sistem-tinjauan-inkonstitusional" tabindex="-1">VI. Sistem Tinjauan Inkonstitusional <a class="header-anchor" href="#vi-sistem-tinjauan-inkonstitusional" aria-label="Permalink to &quot;VI. Sistem Tinjauan Inkonstitusional&quot;">​</a></h2><p>Tinjauan inkonstitusional adalah sistem penting bagi sistem peradilan untuk menjaga otoritas konstitusi:</p><ol><li><strong>Subjek Tinjauan</strong>: Mahkamah Agung Simbiosis adalah satu-satunya subjek tinjauan inkonstitusional, dan mendirikan kamar pengadilan konstitusional yang khusus bertanggung jawab atas tinjauan inkonstitusional.</li><li><strong>Wilayah Tinjauan</strong>: Apakah hukum, peraturan administratif, peraturan daerah, peraturan otonom, interpretasi yudisial, dan dokumen normatif lainnya melanggar konstitusi.</li><li><strong>Inisiasi Tinjauan</strong>: Dapat dimulai secara aktif oleh pengadilan selama pemeriksaan perkara, atau oleh permintaan tinjauan yang diajukan oleh semua makhluk, organisasi, atau lembaga negara.</li><li><strong>Efek Tinjauan</strong>: Dokumen normatif yang dianggap melanggar konstitusi setelah tinjauan, tidak berlaku sejak tanggal publikasi, dan tidak dapat lagi digunakan sebagai dasar putusan.</li><li><strong>Kriteria Tinjauan</strong>: Berdasarkan teks konstitusi dan prinsip konstitusional, dengan mempertimbangkan stabilitas sistem hukum dan adaptabilitas konstitusi.</li></ol><h2 id="vii-jaminan-dan-pengawasan-peradilan" tabindex="-1">VII. Jaminan dan Pengawasan Peradilan <a class="header-anchor" href="#vii-jaminan-dan-pengawasan-peradilan" aria-label="Permalink to &quot;VII. Jaminan dan Pengawasan Peradilan&quot;">​</a></h2><ul><li><strong>Jaminan Anggaran Peradilan</strong>: Anggaran pengadilan dijamin secara terpisah oleh akumulasi publik, tidak dikendalikan oleh lembaga administratif daerah, dan memastikan dasar ekonomi independensi peradilan.</li><li><strong>Informatisasi Peradilan</strong>: Menggunakan teknologi komunikasi antar-plano untuk mendirikan sistem informasi peradilan,实现 informatisasi seluruh proses pendaftaran, pemeriksaan, dan eksekusi, dan meningkatkan efisiensi peradilan.</li><li><strong>Pengawasan Peradilan</strong>: Komite Pengawasan Jangkar mengawasi kegiatan peradilan, dan publik serta media dapat melakukan pengawasan opini publik terhadap kegiatan peradilan, tetapi tidak dapat mengganggu independensi pemeriksaan.</li><li><strong>Bantuan Peradilan</strong>: Memberikan bantuan hukum dan pengurangan atau pembebasan biaya litigasi kepada pihak yang mengalami kesulitan ekonomi, memastikan tidak kehilangan kesempatan perbaikan peradilan karena alasan ekonomi.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Sistem peradilan adalah jaminan akhir dari pemerintahan berdasarkan hukum peradaban simbiosis jangkar. Dengan mendirikan sistem pengadilan empat tingkat, menerapkan independensi peradilan, mendirikan mekanisme penyelesaian sengketa ganda dan sistem tinjauan inkonstitusional, ia memastikan hukum diterapkan secara adil, hak semua makhluk diperbaiki secara efektif, dan memperkuat garis pertahanan pemerintahan berdasarkan hukum untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>49-治理框架与权力制衡 (Kerangka Tata Kelola dan Keseimbangan Kekuatan)</li><li>58-双魂伦理准则 (Kode Etik Dua Jiwa)</li><li>03-共生文明宪章 (Piagam Peradaban Simbiosis)</li></ul>',38)])])}const p=n(s,[["render",r]]);export{o as __pageData,p as default};
